# pod_leadcond_gate.sh : generated by mk_pod_leadcond.py. Runs ON THE POD (bash -s). Dry gates only (one selfcheck per arm), trains nothing.
set -u
W=/workspace/v8proof; cd $W/chain2 || exit 1
n=$(nvidia-smi --query-compute-apps=pid --format=csv,noheader 2>/dev/null | grep -c .); [ "${n:-0}" -lt 3 ] || { echo "GATE-NOT-RUN: $n GPU jobs running, a dry gate would be the fourth"; exit 1; }
a=$(grep -E '^anon ' /sys/fs/cgroup/memory.stat | cut -d' ' -f2); m=$(cat /sys/fs/cgroup/memory.max); [ $((m - a)) -gt 20000000000 ] || { echo 'GATE-NOT-RUN: less than 20 GB of the memory limit free'; exit 1; }
echo "GATE-RAN $(date -u +%Y-%m-%dT%H:%M:%SZ) with $n GPU jobs before"
bash dry_gate.sh arms_leadcond_a.txt LFT_s0 PREREG_V8F_PROOF_ADD35 > $W/chains/leadcond_dry_LFT_s0.out 2>&1; echo "dry gate LFT_s0 rc $?"; tail -n 2 $W/chains/leadcond_dry_LFT_s0.out | cut -c1-300
bash dry_gate.sh arms_leadcond_a.txt LC_s0 PREREG_V8F_PROOF_ADD35 > $W/chains/leadcond_dry_LC_s0.out 2>&1; echo "dry gate LC_s0 rc $?"; tail -n 2 $W/chains/leadcond_dry_LC_s0.out | cut -c1-300
SC=$W/runs/motion_dry/LC_s0/out/selfcheck.json; GA=$W/chains/leadcond_dry_gate_argv.txt
C2_CARD=PREREG_V8F_PROOF_ADD35 bash chain_arms_ft6.sh dryrun_LC_s0 arms_leadcond_a.txt --dry-run | grep '^TRAIN LC_s0: ' | sed 's|^TRAIN LC_s0: ||' | tr ' ' '\n' | tail -n +3 > $GA; echo --selfcheck-only >> $GA
$W/../venv/bin/python gate_token4.py make --selfcheck $SC --argv-file $GA --out $W/chains/leadcond_dry_token_ft6.json --kind HIERFT6 --commit dry --commit-verified false | tail -n 1 | cut -c1-200; echo "token kind HIERFT6 rc ${PIPESTATUS[0]} (must be 0)"
$W/../venv/bin/python gate_token4.py make --selfcheck $SC --argv-file $GA --out $W/chains/leadcond_dry_token_ft.json --kind HIERFT --commit dry --commit-verified false | tail -n 1 | cut -c1-200; echo "token kind HIERFT rc ${PIPESTATUS[0]} (must be 1)"
$W/../venv/bin/python - <<'PYEOF'
import json
S = {}
for a in ('LFT_s0', 'LC_s0'):
    try:
        s = json.load(open('/workspace/v8proof/runs/motion_dry/%s/out/selfcheck.json' % a)); lv = s.get('levers', {}); S[a] = s
        print('SELFCHECK', a, 'dvb', s.get('declared_vs_built'), 'live', (s.get('live') or {}).get('pass'), 'steps_total', s.get('steps_total'), 'init', json.dumps(lv.get('init_ckpt'))[:260], 'lead_sup', lv.get('lead_sup'), 'lead_cond', lv.get('lead_cond'))
        print('   lead_cond probe', json.dumps(s.get('lead_cond_probe'))[:900])
    except Exception as e:
        print('SELFCHECK', a, 'ERR', e)
def flat(d, pre=''):
    out = {}
    if isinstance(d, dict):
        for k, v in d.items():
            if isinstance(v, dict): out.update(flat(v, pre + k + '.'))
            elif isinstance(v, (int, float)) and not isinstance(v, bool): out[pre + k] = float(v)
    return out
if len(S) == 2:
    A, B = flat(S['LFT_s0'].get('live') or {}), flat(S['LC_s0'].get('live') or {})
    common = sorted(set(A) & set(B)); only = sorted(set(A) ^ set(B))
    worst = max([(abs(A[k] - B[k]) / max(abs(A[k]), 1e-12), k) for k in common] or [(float('nan'), '')])
    print('Q3 live fields common %d, largest relative difference %.3e at %s; keys in one only: %s' % (len(common), worst[0], worst[1], only[:12]))
    print('   LFT live', json.dumps(S['LFT_s0'].get('live'))[:500])
PYEOF
